export const WORKFLOW_YAML = "# Liftbay builds on your own GitHub Actions minutes.\n# Liftbay starts this workflow with workflow_dispatch; it does nothing on push or pull requests.\n# The build gets no repository secrets: the runner exchanges this run's GitHub OIDC token for a\n# one-time Liftbay job token, checked against this repository and this workflow file.\n# Docs: https://github.com/liftbay/runner\nname: Liftbay build\nrun-name: Liftbay build ${{ inputs.build_id }}\n\non:\n  workflow_dispatch:\n    inputs:\n      build_id:\n        description: Liftbay build id\n        required: true\n        type: string\n      platform:\n        description: Platform\n        required: true\n        type: choice\n        options: [android, ios]\n      api_url:\n        description: Liftbay API\n        required: false\n        type: string\n        default: https://api.liftbay.dev\n\npermissions:\n  contents: read\n  id-token: write\n\nenv:\n  # Pinned runner release. The archive's SHA-256 is checked before the runner starts.\n  # Release notes and provenance: https://github.com/liftbay/runner/releases/tag/v0.1.2\n  RUNNER_VERSION: \"0.1.2\"\n  RUNNER_SHA256_LINUX_AMD64: \"9b37bfe534b6dc40f81182bdb9dc46461a672f2c28f048743dc8f13f630909b1\"\n  RUNNER_SHA256_DARWIN_ARM64: \"301bf09358a47b48df0cdbd6f60edbac1227e4d7f61e037959d4009ed6ae7f27\"\n\njobs:\n  android:\n    if: inputs.platform == 'android'\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: \"17\"\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n\n      - name: Cache JavaScript dependencies\n        uses: actions/cache@v4\n        with:\n          path: |\n            node_modules\n            ~/.npm\n            ~/.cache/yarn\n            ~/.local/share/pnpm/store\n            ~/.bun/install/cache\n          key: js-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: js-${{ runner.os }}-\n\n      - name: Cache Gradle\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/.gradle/caches\n            ~/.gradle/wrapper\n          key: gradle-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb', 'android/**/*.gradle*', 'android/gradle/wrapper/gradle-wrapper.properties') }}\n          restore-keys: gradle-${{ runner.os }}-\n\n      - name: Install the Liftbay runner\n        env:\n          # Bring your own runner: set the repository variables LIFTBAY_RUNNER_URL (a\n          # liftbay-runner tar.gz you built) and LIFTBAY_RUNNER_SHA256.\n          RUNNER_URL: ${{ vars.LIFTBAY_RUNNER_URL }}\n          RUNNER_SHA256: ${{ vars.LIFTBAY_RUNNER_SHA256 || env.RUNNER_SHA256_LINUX_AMD64 }}\n        run: |\n          set -euo pipefail\n          url=\"${RUNNER_URL:-https://github.com/liftbay/runner/releases/download/v${RUNNER_VERSION}/liftbay-runner_${RUNNER_VERSION}_linux_amd64.tar.gz}\"\n          curl -fsSL --retry 3 -o \"$RUNNER_TEMP/liftbay-runner.tar.gz\" \"$url\"\n          echo \"${RUNNER_SHA256}  $RUNNER_TEMP/liftbay-runner.tar.gz\" | sha256sum -c -\n          tar -xzf \"$RUNNER_TEMP/liftbay-runner.tar.gz\" -C \"$RUNNER_TEMP\" liftbay-runner\n          \"$RUNNER_TEMP/liftbay-runner\" version\n\n      - name: Build\n        env:\n          LIFTBAY_BUILD_ID: ${{ inputs.build_id }}\n          LIFTBAY_API_URL: ${{ inputs.api_url }}\n        run: '\"$RUNNER_TEMP/liftbay-runner\" run'\n\n  ios:\n    if: inputs.platform == 'ios'\n    runs-on: macos-15\n    timeout-minutes: 90\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: maxim-lobanov/setup-xcode@v1\n        with:\n          xcode-version: latest-stable\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n\n      - name: Cache JavaScript dependencies\n        uses: actions/cache@v4\n        with:\n          path: |\n            node_modules\n            ~/.npm\n            ~/Library/Caches/Yarn\n            ~/Library/pnpm/store\n            ~/.bun/install/cache\n          key: js-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: js-${{ runner.os }}-\n\n      # Only the download caches: a restored ios/Pods would make expo prebuild see a half project.\n      - name: Cache CocoaPods\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/Library/Caches/CocoaPods\n            ~/.cocoapods\n          key: pods-${{ runner.os }}-${{ hashFiles('ios/Podfile.lock', 'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: pods-${{ runner.os }}-\n\n      - name: Install the Liftbay runner\n        env:\n          RUNNER_URL: ${{ vars.LIFTBAY_RUNNER_URL_MACOS }}\n          RUNNER_SHA256: ${{ vars.LIFTBAY_RUNNER_SHA256_MACOS || env.RUNNER_SHA256_DARWIN_ARM64 }}\n        run: |\n          set -euo pipefail\n          url=\"${RUNNER_URL:-https://github.com/liftbay/runner/releases/download/v${RUNNER_VERSION}/liftbay-runner_${RUNNER_VERSION}_darwin_arm64.tar.gz}\"\n          curl -fsSL --retry 3 -o \"$RUNNER_TEMP/liftbay-runner.tar.gz\" \"$url\"\n          echo \"${RUNNER_SHA256}  $RUNNER_TEMP/liftbay-runner.tar.gz\" | shasum -a 256 -c -\n          tar -xzf \"$RUNNER_TEMP/liftbay-runner.tar.gz\" -C \"$RUNNER_TEMP\" liftbay-runner\n          \"$RUNNER_TEMP/liftbay-runner\" version\n\n      - name: Build\n        env:\n          LIFTBAY_BUILD_ID: ${{ inputs.build_id }}\n          LIFTBAY_API_URL: ${{ inputs.api_url }}\n        run: '\"$RUNNER_TEMP/liftbay-runner\" run'\n";
